type IconsProps = {
  className?: string;
  colour?: "Yellow" | "White";
  kind?: "+" | "Check" | "x" | "-";
};

function Icons({ className, colour = "Yellow", kind = "+" }: IconsProps) {
  const is = kind === "+";
  const isAndYellow = kind === "-" && colour === "Yellow";
  const isXAndWhite = kind === "x" && colour === "White";
  return (
    <div className={className || `relative rounded-[10px] size-[20px] ${colour === "White" && ["+", "Check", "x"].includes(kind) ? "bg-white" : "bg-[#f1b71c]"}`}>
      <div className="flex flex-row items-center justify-center size-full">
        <div className="content-stretch flex items-center justify-center relative size-full">
          {(is || isAndYellow || isXAndWhite) && (
            <div className={`relative shrink-0 ${isXAndWhite ? "size-[7.071px]" : isAndYellow ? "h-0 w-[10px]" : "size-[10px]"}`}>
              <div className={`absolute ${isXAndWhite ? "inset-[-14.14%]" : isAndYellow ? "inset-[-1px_-10%]" : "inset-[-10%]"}`}>
                <svg className="block size-full" fill="none" height={isXAndWhite ? "9.07107" : isAndYellow ? "2" : "12"} preserveAspectRatio="none" viewBox={isXAndWhite ? "0 0 9.07107 9.07107" : isAndYellow ? "0 0 12 2" : "0 0 12 12"} width={isXAndWhite ? "9.07107" : "12"}>
                  <g id="Group 3">
                    <path d={isXAndWhite ? "M1 8.07107L8.07107 1" : isAndYellow ? "M1 1H11" : "M1 6H11"} id="Vector" stroke="#101636" strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" />
                    {(is || isXAndWhite) && <path d={isXAndWhite ? "M1 1.00001L8.07107 8.07107" : "M6 1V11"} id="Vector_2" stroke="#101636" strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" />}
                  </g>
                </svg>
              </div>
            </div>
          )}
          {kind === "Check" && colour === "White" && (
            <div className="h-[12px] relative shrink-0 w-[14px]" data-name="check">
              <svg className="absolute block inset-0 size-full" fill="none" height="12" preserveAspectRatio="none" viewBox="0 0 14 12" width="14">
                <g id="check">
                  <path d={svgPaths.p2afb7200} id="Vector" stroke="#101636" strokeLinecap="round" strokeWidth="2" />
                </g>
              </svg>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}
